for t in TASKS:
    t.update(updates.get(t['id'],{}))
TASKS[:]=[t for t in TASKS if t['id'].startswith('B')]+[t for t in TASKS if not t['id'].startswith('B')]
# Source work remains behind the original business/data acceptance gate.
for t in TASKS:
    if t['id'] in ['C01','C02'] and 'G0' not in t['predecessors']:t['predecessors'].append('G0')
    if t['id']=='E02':
        t['steps']='Download and hash pinned Qwen3-Embedding-0.6B and Qwen3-Reranker-0.6B snapshots to AWS. '+t['steps']

by={t['id']:t for t in TASKS}
def dates(t,trail=()):
    if 'start_day' in t:return
    assert t['id'] not in trail, 'Dependency cycle'
    for p in t['predecessors']:dates(by[p],trail+(t['id'],))
    t['start_day']=max([t['not_before']]+[by[p]['finish_day']+1 for p in t['predecessors']])
    t['finish_day']=t['start_day']+t['duration']-1
for t in TASKS:dates(t)
# Conservative daily leveling of assigned task and review effort. These are peak
# availability assumptions, not additional headcount or an automatic retainer.
