usage=defaultdict(lambda:defaultdict(float))
ordered=sorted(TASKS,key=lambda t:(t['start_day'],t['finish_day'],t['id']))
for t in ordered:
    t['target_not_before']=t['not_before']
    t['duration']=max(t['duration'],math.ceil(t['hours']/DAILY[t['owner']]),math.ceil(t['review_hours']/DAILY[t['reviewer']]))
    start=max([t['not_before']]+[by[p]['finish_day']+1 for p in t['predecessors']])
    daily=defaultdict(float)
    daily[t['owner']]+=t['hours']/t['duration'];daily[t['reviewer']]+=t['review_hours']/t['duration']
    while any(usage[r][d]+h>DAILY[r]+1e-8 for r,h in daily.items() for d in range(start,start+t['duration'])):start+=1
    t['start_day']=start;t['finish_day']=start+t['duration']-1
    t['not_before']=start
    for r,h in daily.items():
        for d in range(start,t['finish_day']+1):usage[r][d]+=h
assert max(t['finish_day'] for t in TASKS)<=180
assert len({t['id'] for t in TASKS})==len(TASKS)

