def source_routes():
    rows=[]
    for f in ['Broadbridge_Training_Source_Register.csv','Norm_Lieberman_Source_Register.csv']:
        for x in csv.DictReader((ROOT/'output/training-sources'/f).open(encoding='utf-8-sig')):
            id=x['source_id']; name=x.get('name',x.get('title')); url=x.get('source_url',x.get('url',''))
            route='R01'; decision='Acquire and review item rights before use'; taskids='A05 C02 C03 D05'
            if id.startswith('M'):
                route='R09';decision='Candidate; pin and validate before loading';taskids='B02 B03 B04 B05'
                if id in ['M07','M08','M09']:route='R12';decision='Hold; rights or lineage unresolved; no pilot use';taskids='A05'
                if id=='M04':decision='Optional drafting teacher; approved inputs only; independent answer review'
            if id in ['P07','P08']:route='R10';decision='Implement as checked tool, not raw document training';taskids='E03'
            if id=='P06':route='R06';decision='Optional dated context tool; exclude from diagnostic answer labels';taskids='C08'
            if id in ['P09','P10','P11','K04']:route='R12';decision='Held permission review or later practice; not first refining pilot';taskids='A05'
            if id.startswith('D'):route='R12';decision='Hold or later evaluation per original register; not launch SFT';taskids='A05 D09'
            if id=='K01':route='R07 / R03';decision='Original contracted cases preferred; candidate appointment only';taskids='A05 C09 D01'
            if id in ['K02','K03']:route='R11 then R01';decision='Obtain exact licensed full work; separate expert appointment';taskids='A05 C02 D05'
            if id=='K05':route='R04 / R06';decision='Site-only retrieval by default; no shared SFT without grant';taskids='A05 C07 C08'
            if id=='K06':route='R01 / R05';decision='Licensed retrieval only unless separate training grant';taskids='A05 C03 C06'
            if id=='N01':route='R04 / R01';decision='Separate each post, correspondent and embedded asset';taskids='A05 C03 C07'
            if id in ['N09','N10','N11','N13','N14','N15','N16','N17','N19']:route='R11 then R01';decision='Acquire full exact paper/book/article; previews and catalogs are leads only';taskids='A05 C02 D05'
            if id=='N12':route='R11 then R07';decision='License recordings, frames and quizzes separately; evaluator quizzes isolated';taskids='A05 C09 D08'
            rows.append([id,name,route,decision,taskids,url,'Not acquired or processed in this implementation task'])
    assert len(rows)==51
    return rows

